("010EE32ED1", 0, "Đoạn về dị ứng thực phẩm và rối loạn tiêu hóa ở ASD, không định nghĩa ASD.", "", "high"),
("B3060381F2", 3, "Đoạn mở đầu định nghĩa ASD là rối loạn phát triển thần kinh với khiếm khuyết tương tác xã hội, giao tiếp và hành vi/sở thích lặp lại, xuất hiện sớm trong phát triển.", "Autism spectrum disorder (ASD) is a neurodevelopmental disorder characterized by impairments in social interaction and communication as well as a repetitive and/or restricted range of behaviors and interests.", "medium"),
("C709E97102", 1, "Đoạn về rối loạn vận động; chỉ nêu một chi tiết nhỏ là hành vi lặp lại/rập khuôn thuộc tiêu chuẩn chẩn đoán ASD trong DSM.", "The presence of repetitive behaviors or stereotypies is the only motor disorder that is included in the Diagnostic and Statistical Manual of Mental Disorders diagnostic criteria for ASD.", "medium"),
("BE5932399E", 3, "Đoạn định nghĩa đầy đủ ASD là rối loạn phát triển thần kinh với khiếm khuyết kéo dài về giao tiếp, tương tác xã hội và hành vi lặp lại, khởi phát sớm và thường kéo dài suốt đời.", "Autism Spectrum Disorder (ASD) is a neurodevelopmental disorder characterized by persistent deficits in social communication and social interaction across multiple contexts and restricted, repetitive patterns of stereotyped behaviors, interests, or activities.", "high"),
("36E723384C", 3, "Đoạn mở đầu định nghĩa tự kỷ là khuyết tật phát triển thần kinh với các đặc điểm cốt lõi về giao tiếp xã hội, sở thích hẹp và hành vi lặp lại, kèm các chỉ định bổ sung khi chẩn đoán.", "Autism is a neurodevelopmental disability (NDD) characterized by core features such as social communication challenges, focused interests, and repetitive behaviors[1].", "medium"),
("9C67D2358F", 0, "Đoạn về triệu chứng tiêu hóa ở trẻ ASD, không định nghĩa ASD.", "", "high"),
("B25138E4C5", 3, "Đoạn mở đầu định nghĩa ASD là rối loạn phát triển lan tỏa ảnh hưởng kỹ năng xã hội, hành vi lặp lại và giao tiếp, kèm bối cảnh phân loại DSM-IV.", "refers to a pervasive developmental disorder that hinders an individual’s skills in socialisation, creates repetitive behaviours, and impacts expressive or verbal communication with disruptions ranging from moderate to severe [1].", "medium"),
("00C3820CEA", 3, "Đoạn định nghĩa ASD là nhóm tình trạng với suy giảm hành vi xã hội, giao tiếp, ngôn ngữ và phạm vi sở thích hẹp lặp lại, tồn tại suốt đời.", "Autism spectrum disorders (ASD) refer to a range of conditions characterized by some degree of impaired social behavior, communication and language, and a narrow range of interests and activities that are both unique to the individual and carried out repetitively [1].", "high"),
("6B10EF2757", 0, "Đoạn về dinh dưỡng và kén ăn ở trẻ ASD, không định nghĩa ASD.", "", "high"),
("62D4EB9B26", 0, "Bảng nghiên cứu giấc ngủ và hành vi, không định nghĩa ASD.", "", "high"),
("F541ED82C9", 0, "Đoạn về vi sinh đường ruột và triệu chứng tiêu hóa, không định nghĩa ASD.", "", "high"),
("2D109D08B8", 3, "Đoạn định nghĩa ASD theo DSM-5-TR là tình trạng phát triển thần kinh với khó khăn tương tác xã hội, giao tiếp và sở thích hạn hẹp, hành vi lặp lại; kèm tỷ lệ mắc.", "Autism Spectrum Disorder (ASD) is a neurodevelopmental condition characterized by challenges in social interaction and communication and the presence of restricted interests and repetitive behaviors.", "high"),
("350721F52A", 2, "Đoạn mô tả nhóm triệu chứng hành vi/sở thích hạn hẹp, lặp lại của ASD với ví dụ cụ thể; giải thích một phần đặc trưng của ASD.", "These behaviors or interests set ASD apart from conditions defined by problems with social communication and interaction only.", "high"),
("863BC810EC", 0, "Tóm tắt phân tích gộp về bệnh đồng mắc tâm thần, không định nghĩa ASD.", "", "high"),
("6EC94BBCC5", 2, "Đoạn trình bày tiêu chuẩn chẩn đoán B của DSM-5 (hành vi lặp lại, hạn hẹp) và 3 mức độ nặng; hỗ trợ giải thích ASD là gì.", "Severity is based on social communication impairments and restricted, repetitive patterns of behavior.", "high"),
("22AD8B39B7", 0, "Đoạn phương pháp về thang CSBQ và hành vi đi lạc, không định nghĩa ASD.", "", "high"),
("1B710AC006", 3, "Mục 'What is autism spectrum disorder?' định nghĩa ASD là rối loạn thần kinh và phát triển ảnh hưởng tương tác, giao tiếp, học tập, hành vi; nêu đặc điểm theo DSM-5 và nghĩa của 'phổ'.", "Autism spectrum disorder (ASD) is a neurological and developmental disorder that affects how people interact with others, communicate, learn, and behave.", "high"),
("75CEEE6385", 0, "Đoạn về tỷ lệ bệnh đồng mắc tâm thần trong ASD, không định nghĩa ASD.", "", "medium"),
("DD92452034", 1, "Đoạn về bối cảnh Việt Nam; chỉ gián tiếp nêu cách hiểu toàn cầu rằng nguyên nhân tự kỷ phức tạp, do tương tác gen và môi trường.", "Generally, global understandings of autism recognise the aetiology of autism to be complex, with interactive genetic and environmental factors likely contributing to markers of autism", "medium"),
("F6CD1341BA", 3, "Đoạn mở đầu định nghĩa ASD là rối loạn phát triển thần kinh suốt đời với suy giảm hành vi xã hội, giao tiếp, ngôn ngữ và sở thích hẹp lặp lại; dấu hiệu sớm từ 12-18 tháng.", "ASDs are characterized by ‘impaired social behavior, communication and language, and a narrow range of interests and activities that are both unique to the individual and carried out repetitively’.", "medium"),
